<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    lastOp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ENQUEUE;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // 每次入队后打标记</span></span>
